import{_ as o,W as p,s as d,u as l,I as a,ah as r,w as s,Z as n,A as i}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const k=JSON.parse('{"title":"在 Debian 中将用户添加到 SUDOERS 组的 2 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Debian 中将用户添加到 SUDOERS 组的 2 种方法 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"在 Debian 中将用户添加到 SUDOERS 组的 2 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Debian 中将用户添加到 SUDOERS 组的 2 种方法 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230623.0 ⭐️ 2 Ways to Add Users to SUDOERS Group in Debian","title":"在 Debian 中将用户添加到 SUDOERS 组的 2 种方法","tag":"202307"},"relativePath":"202307/20230623.0 ⭐️ 2 Ways to Add Users to SUDOERS Group in Debian.md","filePath":"[post].md"}'),u={name:"202307/20230623.0 ⭐️ 2 Ways to Add Users to SUDOERS Group in Debian.md"};function b(g,e,m,h,S,D){const t=p("Link");return l(),d("div",null,[e[22]||(e[22]=a("h1",{id:"在-debian-中将用户添加到-sudoers-组的-2-种方法",tabindex:"-1"},[s("在 Debian 中将用户添加到 SUDOERS 组的 2 种方法 "),a("a",{class:"header-anchor",href:"#在-debian-中将用户添加到-sudoers-组的-2-种方法","aria-label":"Permalink to 在 Debian 中将用户添加到 SUDOERS 组的 2 种方法"},"​")],-1)),e[23]||(e[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/01/174031t6p74rx6ixlmyjr7.jpg",alt:""})],-1)),e[24]||(e[24]=a("blockquote",null,[a("p",null,"以下是如何将用户添加到 Debian Linux 中的 SUDOERS 组的方法。")],-1)),e[25]||(e[25]=a("p",null,"在 Debian Linux 中，SUDOERS 组在向用户授予管理权限方面发挥着至关重要的作用。将用户添加到 SUDOERS 组使他们能够以 root 权限执行命令，从而为他们提供必要的管理访问权限以在 Debian 系统上执行各种任务。",-1)),a("p",null,[e[1]||(e[1]=s("在安装 Debian Linux 的过程中，如果你将 ")),e[2]||(e[2]=a("code",null,"root",-1)),e[3]||(e[3]=s(" 帐户的密码保留为空，那么系统中的 ")),n(t,{href:"https://www.debian.org/releases/stable/amd64/ch06s03.en.html#user-setup-root"},{default:i(()=>e[0]||(e[0]=[s("创建的第一个用户")])),_:1}),e[4]||(e[4]=s(" 将拥有管理权限。但是，如果你设置了 ")),e[5]||(e[5]=a("code",null,"root",-1)),e[6]||(e[6]=s(" 密码，那么用户名将不具有 sudo 权限。因此，在使用用户帐户执行管理任务时，你可能会遇到以下类似的错误。"))]),e[26]||(e[26]=r('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;username&gt; is not in the sudoers file. This incident will be reported.</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/Before-adding-a-user-to-SUDOERS-group.png" alt="将用户添加到 SUDOERS 组之前"></p><p>本文旨在提供有关在 Debian 中向 SUDOERS 组添加用户的分步指南，确保你可以有效地管理用户权限和系统安全。</p><h3 id="如何将用户添加到-debian-中的-sudoers-组" tabindex="-1">如何将用户添加到 Debian 中的 SUDOERS 组 <a class="header-anchor" href="#如何将用户添加到-debian-中的-sudoers-组" aria-label="Permalink to 如何将用户添加到 Debian 中的 SUDOERS 组">​</a></h3><p>要将用户添加到 Debian 中的 SUDOERS 组，请按照以下简单步骤操作：</p><ul><li>单击“终端”图标或使用快捷键 <code>Ctrl+Alt+T</code>，打开 Debian 系统上的终端。</li><li>使用以下命令切换到 root 用户：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>su -</span></span></code></pre></div><p>系统将提示你提供 root 密码。输入 root 密码并按回车键。</p><p>以 root 用户身份登录后，输入以下命令。确保根据你的用户名进行更改。在此示例中，将 <code>arindam</code> 替换为你的用户名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sbin/addgroup arindam sudo</span></span></code></pre></div><p>如果上面的命令无效，还可以使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -aG sudo arindam</span></span></code></pre></div><p>按退出离开 root 提示符。注销并重新登录。现在你可以使用你的用户名执行任何管理操作。</p><h3 id="另一种方法" tabindex="-1">另一种方法 <a class="header-anchor" href="#另一种方法" aria-label="Permalink to 另一种方法">​</a></h3><p>你可以使用与下面相同的命令进入 root 帐户。使用 root 账号登录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>su -</span></span></code></pre></div><p>然后使用 <code>nano</code> 或 <code>visudo</code> 或任何编辑器打开 <code>/etc/sudoers</code> 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nano /etc/sudoers</span></span></code></pre></div><p>添加以下行和用户名。根据你的用户名替换 <code>arindam</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arindam    ALL=(ALL)    ALL</span></span></code></pre></div><p>保存并关闭文件。然后，注销并重新登录。这应该会给用户名 root 权限。</p><h3 id="验证-sudoers-组成员" tabindex="-1">验证 SUDOERS 组成员 <a class="header-anchor" href="#验证-sudoers-组成员" aria-label="Permalink to 验证 SUDOERS 组成员">​</a></h3><p>要验证用户是否已成功添加到 SUDOERS 组，你可以打开一个新的终端窗口并输入以下命令。将 <code>arindam</code> 替换为你添加到 SUDOERS 组的用户的实际用户名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo -l -U arindam</span></span></code></pre></div><p>如果用户是 SUDOERS 组的成员，你将看到他们拥有的权限列表。这是一个示例，你可以看到我的用户名具有所有访问权限。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/After-granting-priviledges.png" alt="授予权限后"></p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to 结束语">​</a></h3><p>将用户添加到 SUDOERS 组将授予他们重要的管理权限。在授予用户此类访问权限之前，仔细考虑用户的可信度和责任非常重要。sudo 使用不当可能会导致系统意外损坏或受损。</p><p>请记住在委派管理权限时要小心谨慎，并定期检查用户权限以维护安全的 Debian 系统。</p><p><em>（题图：MJ/c71c2f28-51c7-44c7-87be-af88088bf459）</em></p><hr>',31)),a("p",null,[e[8]||(e[8]=s("via: ")),n(t,{href:"https://www.debugpoint.com/add-users-sudoers/"},{default:i(()=>e[7]||(e[7]=[s("https://www.debugpoint.com/add-users-sudoers/")])),_:1})]),a("p",null,[e[13]||(e[13]=s("作者：")),n(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>e[9]||(e[9]=[s("Arindam")])),_:1}),e[14]||(e[14]=s(" 选题：")),n(t,{href:"https://github.com/lkxed/"},{default:i(()=>e[10]||(e[10]=[s("lkxed")])),_:1}),e[15]||(e[15]=s(" 译者：")),n(t,{href:"https://github.com/geekpi"},{default:i(()=>e[11]||(e[11]=[s("geekpi")])),_:1}),e[16]||(e[16]=s(" 校对：")),n(t,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:i(()=>e[12]||(e[12]=[s("校对者ID")])),_:1})]),a("p",null,[e[19]||(e[19]=s("本文由 ")),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>e[17]||(e[17]=[s("LCTT")])),_:1}),e[20]||(e[20]=s(" 原创编译，")),n(t,{href:"https://linux.cn/"},{default:i(()=>e[18]||(e[18]=[s("Linux中国")])),_:1}),e[21]||(e[21]=s(" 荣誉推出"))])])}const f=o(u,[["render",b]]);export{k as __pageData,f as default};
